import{_ as d,o as t,c as o,ag as c}from"./chunks/framework.DQe9aj1R.js";const m=JSON.parse('{"title":"以前の書き方から移る","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compatibility.md","filePath":"guide/compatibility.md","lastUpdated":1789803897000}'),r={name:"guide/compatibility.md"};function a(n,e,i,s,l,g){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="以前の書き方から移る" tabindex="-1">以前の書き方から移る <a class="header-anchor" href="#以前の書き方から移る" aria-label="Permalink to &quot;以前の書き方から移る&quot;">​</a></h1><p>v8 では、よく使う入力・描画・乱数・位置情報・カメラの入口を足し、廃止予定だった宣言と旧い入口を削除しました。新しい課題は、削除した名前に戻さないでください。</p><p>機械生成のAPIページは、ソースより遅れていることがあります。移したあとの正しさは <code>Runtime/Scripts</code> で確認します。</p><h2 id="ポインター" tabindex="-1">ポインター <a class="header-anchor" href="#ポインター" aria-label="Permalink to &quot;ポインター&quot;">​</a></h2><p>1本の指やマウスは <code>gc.Pointer</code>、複数は <code>gc.Pointers</code> です。イベントの発生順が要るときだけ <code>gc.PointerEvents</code> を使います。タップは <code>gc.Taps</code> です。</p><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>LastPointerX</code> / <code>LastPointerY</code></td><td><code>gc.Pointer.X</code> / <code>gc.Pointer.Y</code></td></tr><tr><td><code>LastPointerPoint</code> / <code>LastPointerEvent</code> / <code>LastPointerTime</code> / <code>LastPointerFrame</code></td><td><code>gc.Pointer</code> か <code>gc.PointerEvents</code></td></tr><tr><td><code>IsTouchBegan()</code></td><td><code>gc.Pointer.Down</code></td></tr><tr><td><code>IsTouched()</code></td><td>そのフレームに接触があるか。<code>Down</code> / <code>Held</code> / <code>Up</code> を見る</td></tr><tr><td><code>IsTouchEnded()</code></td><td><code>gc.Pointer.Up</code></td></tr><tr><td><code>IsTapped()</code></td><td><code>gc.Taps.Count != 0</code></td></tr><tr><td><code>IsTapped(out point)</code></td><td><code>gc.Taps</code> の <code>Count &gt; 0</code> を確認してから <code>gc.Taps[0]</code> を使う。位置は押し始めた位置</td></tr><tr><td><code>TryGetPointerEventAll</code> から始める導入</td><td><code>gc.Pointers</code>。順序が要るときだけ <code>gc.PointerEvents</code></td></tr><tr><td><code>TryGetPointerEvent</code> / <code>TryGetPointerTrace</code></td><td>削除。<code>gc.Pointers</code> か <code>gc.PointerEvents</code></td></tr><tr><td><code>GetPointerX(i)</code></td><td><code>gc.Pointers[i].X</code></td></tr><tr><td><code>PointerCount</code></td><td>今の一覧は <code>gc.Pointers.Count</code>。変化の個数は <code>gc.PointerEvents.Count</code></td></tr><tr><td><code>PointerBeginCount</code> / <code>PointerEndCount</code></td><td><code>Down</code> / <code>Up</code> を数える</td></tr><tr><td><code>PointerTapCount</code> / <code>TryGetPointerTapPoint</code></td><td><code>gc.Taps.Count</code> / <code>gc.Taps[i]</code></td></tr><tr><td><code>GcPointerTrace</code></td><td>削除。状態は <code>gc.Pointers[i]</code></td></tr><tr><td>中断が <code>End</code> に混ざる</td><td><code>Cancelled</code>。タップや普通の解放には数えない</td></tr><tr><td>代表の指を離すと、残った指へ引き継ぐ</td><td>引き継がない。残った指は一覧で追う</td></tr></tbody></table><p><code>LastPointer*</code> は過去フレームの最後のイベントも残していたが、<code>Pointer</code> と <code>PointerEvents</code> は同じ意味ではなく現在のフレームを指すので、過去の座標を使う場合は自分で値を保存する。</p><p>タップは、短時間で動きが小さい正常な解放だけです。押し始めの <code>Down</code> とは別です。位置は押し始めた点です。感度は <code>gc.TapSettings</code> のままです。<code>MaxDistance</code> は途中の移動を足した距離（キャンバス単位）、<code>MaxDuration</code> は秒です。既定は 25 と 0.125 です。</p><p>同じ対象を、状態の一覧とイベント列の両方で動かすと二重に処理されます。どちらか一方にします。</p><h2 id="キーボード" tabindex="-1">キーボード <a class="header-anchor" href="#キーボード" aria-label="Permalink to &quot;キーボード&quot;">​</a></h2><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>IsKeyDown(Key.Space)</code></td><td><code>gc.Key(GcKey.Space).Down</code></td></tr><tr><td><code>IsKeyPress(Key.Space)</code></td><td><code>gc.Key(GcKey.Space).Held</code></td></tr><tr><td><code>IsKeyHold(Key.Space)</code></td><td>押した瞬間を除く押し続け。今は <code>Held</code> が真かつ <code>Down</code> が偽</td></tr><tr><td><code>IsKeyUp(Key.Space)</code></td><td><code>gc.Key(GcKey.Space).Up</code></td></tr><tr><td><code>IsAnyKey</code> / <code>IsAnyKeyDown</code> / <code>IsAnyKeyHold</code> / <code>IsAnyKeyPress</code> / <code>IsAnyKeyUp</code></td><td>削除。見たいキーを <code>gc.Key</code> で読む</td></tr><tr><td><code>TryGetKeyEvent</code> / <code>TryGetKeyEventAll</code></td><td><code>gc.KeyEvents</code></td></tr><tr><td><code>TryGetKeyTrace</code> / <code>TryGetKeyTraceAll</code> / <code>GcKeyTrace</code></td><td>削除。状態は <code>gc.Key</code>、変化は <code>gc.KeyEvents</code></td></tr><tr><td><code>KeyDownCount</code> / <code>KeyHoldCount</code> / <code>KeyPressCount</code> / <code>KeyUpCount</code></td><td>削除。<code>gc.KeyEvents.Count</code> は Down と Up と Cancelled をすべて含む変化の数で、DownCount や UpCount そのものではない。必要な Phase で数える。押し続けは <code>gc.Key(...).Held</code> を使う。Hold イベントは存在しない</td></tr><tr><td><code>KeyEscape</code></td><td><code>gc.Key(GcKey.Escape)</code></td></tr><tr><td><code>GetKeyPressDuration</code> / <code>GetKeyPressFrameCount</code></td><td><code>GetKeyPressDuration</code> は <code>gc.Key(...).Duration</code> へ置換できる。<code>GetKeyPressFrameCount</code> は削除で、直接の代替はない。<code>Duration</code> は秒で、フレーム数ではない。フレーム数が必要なら、自分で数える</td></tr><tr><td><code>KeyCode</code> や文字1つを渡す引数</td><td>削除済み。<code>GcKey</code> を使う</td></tr><tr><td>イベントの <code>Phase.Hold</code></td><td>削除。押し続けは <code>gc.Key(...).Held</code></td></tr></tbody></table><p><code>gc.KeyEvents</code> は <code>GcReadOnlyList&lt;GcKeyEvent&gt;</code> です。<code>Count</code> と添字で、このフレームの入力変化を順に読みます。<code>Key</code> は <code>GcKey</code>、<code>Phase</code> は <code>Down</code> / <code>Up</code> / <code>Cancelled</code> です。変化がなければ空です。<code>PointerEvents</code> と同じく、フレームをまたいで貯める一覧ではありません。</p><h2 id="時間" tabindex="-1">時間 <a class="header-anchor" href="#時間" aria-label="Permalink to &quot;時間&quot;">​</a></h2><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>TimeSinceStartup</code> が <code>float</code></td><td><code>double</code> の秒</td></tr><tr><td>ポインター / キーの <code>Duration</code></td><td>どちらも <code>double</code> の秒</td></tr><tr><td>イベントの <code>Time</code></td><td><code>double</code> の秒</td></tr><tr><td><code>TimeSincePrevFrame</code></td><td><code>float</code> の秒のまま。座標の更新に使う</td></tr></tbody></table><p>長い経過どうしの差を <code>float</code> で取らないでください。</p><h2 id="乱数" tabindex="-1">乱数 <a class="header-anchor" href="#乱数" aria-label="Permalink to &quot;乱数&quot;">​</a></h2><p>整数の範囲は、上限を含む仕様から、上限を含まない仕様へ変わりました。小数の範囲は以前から上限を含みません。</p><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>gc.Random()</code></td><td>0 以上 1 未満の <code>float</code>。同じ</td></tr><tr><td>なし</td><td><code>gc.Random(6)</code> は 0 以上 6 未満の整数</td></tr><tr><td><code>gc.Random(1, 6)</code> が 1 から 6</td><td><code>gc.Random(1, 7)</code> が 1 から 6。サイコロはこちら</td></tr><tr><td><code>gc.Random(0, array.Length - 1)</code></td><td><code>gc.Random(array.Length)</code></td></tr><tr><td>空や逆の範囲</td><td><code>ArgumentOutOfRangeException</code></td></tr><tr><td>小数の NaN / Infinity</td><td><code>ArgumentOutOfRangeException</code></td></tr></tbody></table><p><code>gc.SetRandomSeed</code> で再現はできます。以前の版と同じ乱数列になることは約束しません。</p><h2 id="位置情報" tabindex="-1">位置情報 <a class="header-anchor" href="#位置情報" aria-label="Permalink to &quot;位置情報&quot;">​</a></h2><p>旧い位置情報の入口は削除しました。<code>GcGeolocationEvent</code>、<code>StartGeolocationService</code>、<code>StopGeolocationService</code>、<code>TryGetGeolocationEvent</code>、<code>GeolocationStatus</code>、<code>HasUserAuthorizedPermissionGeolocation</code> はありません。</p><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>StartGeolocationService</code></td><td><code>gc.Location.Start()</code></td></tr><tr><td><code>StopGeolocationService</code></td><td><code>gc.Location.Stop()</code></td></tr><tr><td><code>TryGetGeolocationEvent</code></td><td><code>gc.Location.TryGetSample</code></td></tr><tr><td><code>GeolocationStatus</code></td><td><code>gc.Location.Status</code></td></tr><tr><td>権限要求と起動を別々に書く導入</td><td><code>Start</code> が許可の確認から入る</td></tr></tbody></table><p>値の有無は <code>TryGetSample</code> で一度に判断します。Editor では未対応です。緯度経度は <code>double</code> です。Editor 用の固定座標を、測位の成功として出さないでください。</p><h2 id="カメラ" tabindex="-1">カメラ <a class="header-anchor" href="#カメラ" aria-label="Permalink to &quot;カメラ&quot;">​</a></h2><p>旧いカメラの入口は削除しました。<code>IInputCamera</code> は残っており、新しいメンバーは <code>Camera</code> と <code>DrawCamera</code> です。旧いメンバーと <code>IInputCameraEx</code> はありません。コールバック、<code>requestId</code>、許可待ちの変数、<code>PauseGame</code>、再生中フラグは、簡単な例では不要です。</p><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>PlayCameraImage</code></td><td><code>gc.Camera.Start()</code>。許可から入る。希望の幅・高さ・fps は引数</td></tr><tr><td><code>StopCameraImage</code></td><td><code>gc.Camera.Stop()</code>。許可待ちも取り消す</td></tr><tr><td><code>RequestUserAuthorizedPermissionCameraAsync</code></td><td>削除。<code>Start</code> が許可の確認から入る</td></tr><tr><td><code>HasUserAuthorizedPermissionCamera</code></td><td><code>gc.Camera.Permission</code></td></tr><tr><td><code>PauseCameraImage</code></td><td>一時停止の入口はない。止めるなら <code>Stop</code>。背面では GameCanvas が止める</td></tr><tr><td><code>IsPlayingCameraImage</code></td><td><code>gc.Camera.Status == GcCameraState.Running</code>。最初の有効な映像を受け取ったとき。<code>PlayCameraImage</code> の成功とは違う</td></tr><tr><td><code>DidUpdateCameraImageThisFrame</code></td><td><code>gc.Camera.Updated</code></td></tr><tr><td><code>TryGetCameraImage</code> / <code>TryGetCameraImageAll</code> / <code>CameraDevices</code> / <code>CameraDeviceCount</code></td><td>許可のあと <code>gc.Camera.Devices</code>。使用中のカメラは <code>gc.Camera.Device</code>。<code>Count</code> と添字で読む</td></tr><tr><td><code>TryGetCameraImage(deviceName)</code></td><td><code>Devices</code> から名前で探すか、<code>Start(device)</code></td></tr><tr><td><code>UpdateCameraDevice</code></td><td>削除。<code>Start</code> の許可のあと調べる</td></tr><tr><td><code>TryGetCameraImageSize</code></td><td><code>gc.Camera.Width</code> / <code>Height</code>。向きを補正した整数。<code>Running</code> 以外は 0</td></tr><tr><td><code>TryGetCameraImageRotation</code></td><td><code>gc.Camera.Rotation</code>。以前は <code>Repeat(-nativeAngle, 360)</code>。今は <code>Repeat(nativeAngle, 360)</code> の時計回りの補正です。符号と向きが逆です。<code>DrawCamera</code> は自動で直します</td></tr><tr><td><code>IsFlippedCameraImage</code></td><td><code>gc.Camera.IsMirrored</code></td></tr><tr><td><code>TryChangeCameraImageResolution</code></td><td><code>Start</code> の希望値。実際の大きさは映像のあと</td></tr><tr><td><code>GetPrimaryCameraResolution</code></td><td>削除。希望値は <code>Start</code> の引数</td></tr><tr><td><code>FocusCameraImage</code></td><td><code>gc.Camera.Focus(x, y)</code>。左下 (0, 0)、右上 (1, 1)。解除は <code>ResetFocus</code></td></tr><tr><td><code>DrawCameraImage</code></td><td><code>gc.DrawCamera</code>。基準点は <code>SetRectAnchor</code>。描画は開始しない。<code>GcPoint</code> と <code>float2</code> の位置もある。<code>DrawCamera(GcRect)</code> は <code>rect.Rotation</code> を使う。追加の回転は数値や点の引数だけ</td></tr><tr><td><code>DrawCameraImage(..., autoPlay)</code></td><td>削除。描画のついでに開始しない</td></tr><tr><td><code>DrawCameraImage</code> の width / height</td><td>今は描く先の大きさ。以前は元映像の解像度が掛かっていた。引数なしの実寸はこの修正の対象外です</td></tr><tr><td><code>GetOrCreateCameraTexture</code></td><td>削除。低レベルのテクスチャは出さない</td></tr><tr><td>複数カメラの同時再生</td><td>このサービスでは非対応</td></tr><tr><td>デプスカメラ</td><td>このサービスでは非対応。デプスカメラは一覧に出ません</td></tr></tbody></table><p><code>Start</code> は操作のときに呼びます。呼び直すと前の処理を止めて始め直します。<code>Running</code> は最初の有効な映像を受け取った状態です。アプリが背面に回ると GameCanvas が止め、自動では再開しません。許可の画面で中断した場合も、戻ってからもう一度 <code>Start</code> します。</p><h2 id="画像と文字と矩形" tabindex="-1">画像と文字と矩形 <a class="header-anchor" href="#画像と文字と矩形" aria-label="Permalink to &quot;画像と文字と矩形&quot;">​</a></h2><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>TryGetImage</code> してから <code>DrawImage</code></td><td><code>gc.DrawImage(&quot;BlueSky.png&quot;, x, y)</code></td></tr><tr><td><code>DrawRightString</code> / <code>DrawCenterString</code></td><td><code>gc.SetStringAnchor(...)</code> のあと <code>DrawString</code></td></tr><tr><td><code>SetColor</code> の float と byte の取り違え</td><td><code>SetColor(int, int, int, int = 255)</code>。0 から 255。範囲外は丸める</td></tr><tr><td>0 から 1 の色</td><td><code>GcColor.FromNormalized</code>。NaN は不可</td></tr><tr><td><code>GcRect</code> の <code>Radian</code></td><td>公開しない。<code>Rotation</code> に度数を入れる</td></tr><tr><td><code>rect.Degree()</code></td><td><code>rect.Rotation</code></td></tr><tr><td><code>new GcRect(x, y, w, h, radian)</code></td><td><code>new GcRect(x, y, w, h)</code>。回転は <code>{ Rotation = 30 }</code> か <code>GcRect.FromDegrees(x, y, w, h, 30)</code></td></tr><tr><td>描画や座標回転の <code>degree</code> 引数</td><td><code>rotation</code>。時計回りの度。<code>Sin</code> / <code>Cos</code> の <code>degree</code> はそのまま</td></tr></tbody></table><p>図形、画像、Texture、カメラ映像、オンライン画像は <code>SetRectAnchor</code> です。文字は <code>SetStringAnchor</code> です。引数なし、<code>GcPoint</code>、数値の x,y、<code>GcRect</code> のどれでも、直前の設定を使います。任意の画像の有無で分岐するときや、同じハンドルを繰り返すときだけ <code>TryGetImage</code> を使います。カメラ映像は <code>gc.DrawCamera</code> です。幅と高さは描く先の大きさです。</p><p>矩形指定の <code>DrawImage</code> / <code>DrawString</code> の <code>rotation</code> は、矩形の回転へ加算します。渡した <code>GcRect</code> 自体は変わりません。</p><h2 id="アクター" tabindex="-1">アクター <a class="header-anchor" href="#アクター" aria-label="Permalink to &quot;アクター&quot;">​</a></h2><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>GetActorList&lt;T&gt;</code> が返した <code>ReadOnlyActorList&lt;T&gt;</code></td><td><code>TryGetActorAll&lt;T&gt;</code></td></tr></tbody></table><p><code>GetActorList</code> と <code>ReadOnlyActorList&lt;T&gt;</code> はありません。</p>',34)])])}const y=d(r,[["render",a]]);export{m as __pageData,y as default};
